import React, { useState, useEffect } from 'react';
import { machineApi } from '../api/client';
import {
  Sparkles,
  Sliders,
  Gauge,
  Thermometer,
  Zap,
  TrendingUp,
  AlertTriangle,
  CheckCircle2,
  Play,
  RotateCcw,
  Layers,
  Cpu,
  DollarSign,
  ShieldAlert,
  Search,
  Activity,
  Droplets,
  Wind,
  Wrench,
  Clock,
  PieChart,
  Award,
} from 'lucide-react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const WhatIfSimulationPage = () => {
  // Loom Search & Selection State
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMachineId, setSelectedMachineId] = useState('LOOM-101');
  const [machines, setMachines] = useState([]);
  const [currentMachine, setCurrentMachine] = useState(null);

  // Simulation Slider Input Controls
  const [targetRpm, setTargetRpm] = useState(980);
  const [jetPressure, setJetPressure] = useState(4.8);
  const [ambientTemp, setAmbientTemp] = useState(32);
  const [humidityPct, setHumidityPct] = useState(65);
  const [yarnTensionN, setYarnTensionN] = useState(18);
  const [shiftHours, setShiftHours] = useState(24);
  const [coolingFanPct, setCoolingFanPct] = useState(85);
  const [yarnQuality, setYarnQuality] = useState('Combed Cotton 40s');
  const [deferredMaintDays, setDeferredMaintDays] = useState(0);

  useEffect(() => {
    fetchMachines();
  }, []);

  const fetchMachines = async () => {
    try {
      const res = await machineApi.getAll();
      if (res.data.success) {
        setMachines(res.data.data);
        const initial = res.data.data.find((m) => m.machineId === 'LOOM-101') || res.data.data[0];
        if (initial) {
          setCurrentMachine(initial);
          loadMachineMetricsIntoSliders(initial);
        }
      }
    } catch (err) {
      console.error('Failed to fetch machines for simulation:', err);
    }
  };

  const loadMachineMetricsIntoSliders = (m) => {
    const tel = m.telemetry || {};
    setTargetRpm(Number(tel.rpm) || 980);
    setJetPressure(Number(tel.airPressureBar) || 4.8);
    setAmbientTemp(Number(tel.temperature) || 32);
    setHumidityPct(Number(tel.humidity) || 65);
    setYarnTensionN(Number(tel.yarnTensionN) || 18);
  };

  const handleSelectMachine = (mId) => {
    setSelectedMachineId(mId);
    if (mId === 'ALL') {
      setCurrentMachine(null);
      setTargetRpm(980);
      setJetPressure(4.8);
      setAmbientTemp(32);
      setHumidityPct(65);
      setYarnTensionN(18);
    } else {
      const found = machines.find((m) => m.machineId === mId || m._id === mId);
      if (found) {
        setCurrentMachine(found);
        loadMachineMetricsIntoSliders(found);
      }
    }
  };

  const filteredMachines = machines.filter(
    (m) =>
      m.machineId.toLowerCase().includes(searchTerm.toLowerCase()) ||
      m.assetName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (m.factoryName || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
      (m.productionLine || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  const applyPreset = (preset) => {
    switch (preset) {
      case 'rush':
        setTargetRpm(1150);
        setJetPressure(5.8);
        setAmbientTemp(36);
        setHumidityPct(55);
        setYarnTensionN(24);
        setShiftHours(24);
        setCoolingFanPct(100);
        setYarnQuality('Heavy Canvas Denim');
        setDeferredMaintDays(14);
        break;
      case 'eco':
        setTargetRpm(820);
        setJetPressure(4.0);
        setAmbientTemp(26);
        setHumidityPct(70);
        setYarnTensionN(16);
        setShiftHours(16);
        setCoolingFanPct(70);
        setYarnQuality('Combed Cotton 40s');
        setDeferredMaintDays(0);
        break;
      case 'life':
        setTargetRpm(750);
        setJetPressure(3.8);
        setAmbientTemp(24);
        setHumidityPct(75);
        setYarnTensionN(14);
        setShiftHours(12);
        setCoolingFanPct(90);
        setYarnQuality('Carded Cotton');
        setDeferredMaintDays(0);
        break;
      case 'heatwave':
        setTargetRpm(960);
        setJetPressure(4.6);
        setAmbientTemp(44);
        setHumidityPct(45);
        setYarnTensionN(20);
        setShiftHours(24);
        setCoolingFanPct(100);
        setYarnQuality('Polyester Blend');
        setDeferredMaintDays(7);
        break;
      default:
        resetSimulation();
    }
  };

  const resetSimulation = () => {
    if (currentMachine) {
      loadMachineMetricsIntoSliders(currentMachine);
    } else {
      setTargetRpm(980);
      setJetPressure(4.8);
      setAmbientTemp(32);
      setHumidityPct(65);
      setYarnTensionN(18);
    }
    setShiftHours(24);
    setCoolingFanPct(85);
    setDeferredMaintDays(0);
  };

  // Baseline Metrics
  const tel = currentMachine?.telemetry || {
    temperature: '54.2',
    vibration: '1.45',
    rpm: 980,
    powerKw: '14.2',
    motorCurrentA: '28.5',
    humidity: '65.2',
    airPressureBar: '4.8',
    yarnTensionN: '18.4',
    fabricOutputMhr: '98.4',
    defectCount: 2,
    runningHours: 4210,
    failureRiskPct: 4.2,
    maintenanceDueDays: 12,
  };

  // Advanced Mathematical Dynamic What-If Calculations
  const baseRpm = Number(tel.rpm) || 980;
  const baseYieldMhr = Number(tel.fabricOutputMhr) || 98.4;
  const rpmRatio = targetRpm / (baseRpm || 1);
  const pressureRatio = jetPressure / (Number(tel.airPressureBar) || 4.8 || 1);
  const fanCoolingFactor = coolingFanPct / 85;

  // Temperature simulation taking ambient heat + fan cooling into account
  const simTemp = (
    Number(tel.temperature) +
    (targetRpm - baseRpm) * 0.04 +
    (ambientTemp - 32) * 0.4 -
    (fanCoolingFactor - 1) * 6
  ).toFixed(1);

  // Vibration simulation
  const simVibration = (
    Number(tel.vibration) *
    Math.pow(rpmRatio, 1.6) *
    (1 + (yarnTensionN - 18) * 0.02)
  ).toFixed(2);

  // Power & Current simulation
  const simPowerKw = (
    Number(tel.powerKw) *
    Math.pow(rpmRatio, 1.45) *
    pressureRatio
  ).toFixed(1);

  const simMotorCurrentA = (
    Number(tel.motorCurrentA) *
    rpmRatio *
    (1 + (simTemp - 54.2) * 0.008)
  ).toFixed(1);

  // Fabric Output & Yield simulation
  const simFabricOutputMhr = (
    baseYieldMhr *
    rpmRatio *
    (1 - Math.max(0, simTemp - 60) * 0.01)
  ).toFixed(1);

  const totalSimOutputMeters = Math.round(parseFloat(simFabricOutputMhr) * shiftHours);

  // Defect Count simulation
  const simDefectCount = Math.max(
    0,
    Math.round(
      Number(tel.defectCount) +
        (targetRpm > 1080 ? 4 : 0) +
        (yarnTensionN > 22 ? 3 : 0) +
        (ambientTemp > 40 ? 5 : 0)
    )
  );

  // Failure Risk simulation
  const tempOverheatFactor = simTemp > 65 ? (simTemp - 65) * 1.8 : 0;
  const simFailureRiskPct = (
    Number(tel.failureRiskPct) *
    Math.pow(rpmRatio, 1.8) *
    (1 + tempOverheatFactor * 0.08) *
    (1 + deferredMaintDays * 0.025)
  ).toFixed(1);

  // RUL Days simulation
  const baseRul = currentMachine?.machineHealth?.remainingUsefulLifeDays || 165;
  const simRulDays = Math.max(
    12,
    Math.round(
      baseRul / (rpmRatio * (1 + tempOverheatFactor * 0.05 + deferredMaintDays * 0.03))
    )
  );

  // Financial Calculations
  const fabricPricePerMeter = 4.5; // $4.50 / meter
  const powerCostPerKwh = 0.15; // $0.15 / kWh
  const defectScrapLossPerUnit = 25; // $25 loss per defect

  const grossRevenue = Math.round(totalSimOutputMeters * fabricPricePerMeter);
  const totalPowerCost = Math.round(parseFloat(simPowerKw) * shiftHours * powerCostPerKwh);
  const totalDefectCost = simDefectCount * defectScrapLossPerUnit;
  const netProfit = grossRevenue - totalPowerCost - totalDefectCost;

  // Comparison Bar Chart
  const chartData = {
    labels: ['Yield (Meters/10)', 'Failure Risk (%)', 'Power (kW)', 'Motor Temp (°C)', 'RUL Days'],
    datasets: [
      {
        label: `${currentMachine ? currentMachine.machineId : 'Baseline'} Baseline`,
        data: [
          Math.round((baseYieldMhr * 24) / 10),
          parseFloat(tel.failureRiskPct || 4.2),
          Math.round(Number(tel.powerKw)),
          Math.round(Number(tel.temperature)),
          baseRul,
        ],
        backgroundColor: '#4F46E5',
        borderRadius: 4,
      },
      {
        label: 'Simulated What-If State',
        data: [
          Math.round(totalSimOutputMeters / 10),
          parseFloat(simFailureRiskPct),
          Math.round(parseFloat(simPowerKw)),
          Math.round(parseFloat(simTemp)),
          simRulDays,
        ],
        backgroundColor: simFailureRiskPct > 15 ? '#E11D48' : '#059669',
        borderRadius: 4,
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'top',
        align: 'end',
        labels: { color: '#0F172A', font: { family: 'Plus Jakarta Sans', size: 12, weight: '800' } },
      },
    },
    scales: {
      x: { ticks: { color: '#0F172A', font: { family: 'Plus Jakarta Sans', size: 11, weight: '800' } } },
      y: { ticks: { color: '#0F172A', font: { family: 'Plus Jakarta Sans', size: 11, weight: '800' } } },
    },
  };

  return (
    <div>
      {/* Header */}
      <div className="page-header">
        <div className="page-title-group">
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <h1>What-If AI Simulation Engine</h1>
            <span className="badge badge-high" style={{ background: 'var(--status-critical-bg)', color: 'var(--status-critical)', border: '1px solid rgba(124, 58, 237, 0.3)' }}>
              <Sparkles size={14} /> MULTI-PARAMETRIC AI SIMULATOR
            </span>
          </div>
          <p>Simulate Operating Speed, Air Pressure, Ambient Temp, Humidity, & Tension Across All 13 Operational Metrics</p>
        </div>

        <button className="btn btn-secondary" onClick={resetSimulation}>
          <RotateCcw size={16} /> Reset Simulation Parameters
        </button>
      </div>

      {/* DEDICATED LOOM SEARCH & SELECTOR BAR */}
      <div
        className="glass-card"
        style={{
          padding: '1.25rem 1.5rem',
          marginBottom: '1.75rem',
          display: 'flex',
          gap: '1.25rem',
          alignItems: 'center',
          background: 'var(--bg-card)',
          flexWrap: 'wrap',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', minWidth: '220px' }}>
          <Search size={20} style={{ color: 'var(--accent-primary)' }} />
          <span style={{ fontWeight: '800', fontSize: '0.95rem', color: '#0F172A' }}>Search & Inspect Loom:</span>
        </div>

        <div className="search-box" style={{ flex: 1, minWidth: '240px' }}>
          <Search size={16} className="search-icon" />
          <input
            type="text"
            className="search-input"
            placeholder="Search Loom by ID, Asset Name, Plant, or Production Line..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <select
          className="filter-select"
          style={{ minWidth: '320px', fontWeight: '800' }}
          value={selectedMachineId}
          onChange={(e) => handleSelectMachine(e.target.value)}
        >
          <option value="ALL">🌐 Simulate Entire Fleet Average (20 Looms)</option>
          {filteredMachines.map((m) => (
            <option key={m._id || m.machineId} value={m.machineId}>
              {m.machineId} — {m.assetName} ({m.factoryName || 'Primary Mill'} • {m.productionLine})
            </option>
          ))}
        </select>
      </div>

      {/* Preset What-If Scenario Quick Buttons */}
      <div style={{ display: 'flex', gap: '0.85rem', flexWrap: 'wrap', marginBottom: '1.75rem' }}>
        <button className="btn btn-secondary btn-sm" onClick={() => applyPreset('rush')} style={{ borderLeft: '4px solid var(--status-maintenance)' }}>
          🚀 Rush Order Max Throughput
        </button>
        <button className="btn btn-secondary btn-sm" onClick={() => applyPreset('eco')} style={{ borderLeft: '4px solid var(--status-running)' }}>
          🍃 Eco Energy-Saver Mode
        </button>
        <button className="btn btn-secondary btn-sm" onClick={() => applyPreset('life')} style={{ borderLeft: '4px solid var(--accent-primary)' }}>
          🛡️ Max Asset Lifespan Mode
        </button>
        <button className="btn btn-secondary btn-sm" onClick={() => applyPreset('heatwave')} style={{ borderLeft: '4px solid var(--status-idle)' }}>
          ☀️ Summer Heatwave Operating Mode
        </button>
      </div>

      {/* Expanded Multi-Parametric Sliders Controls */}
      <div className="glass-card" style={{ padding: '1.75rem', marginBottom: '1.75rem' }}>
        <div style={{ borderBottom: '1px solid var(--border-subtle)', paddingBottom: '0.85rem', marginBottom: '1.25rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h3 style={{ fontSize: '1.1rem', fontWeight: '800', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <Sliders size={20} style={{ color: 'var(--accent-primary)' }} /> Expanded What-If Control Sliders (7 Operational Knobs)
          </h3>
          <span style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', fontWeight: '800' }}>Live Interactive Simulation</span>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '1.25rem' }}>
          {/* Slider 1: Target Speed (RPM) */}
          <div className="form-group">
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem', fontWeight: '800' }}>
              <span style={{ color: '#0F172A' }}>1. Target Speed (RPM)</span>
              <span style={{ color: 'var(--accent-primary)' }}>{targetRpm} RPM</span>
            </div>
            <input
              type="range" min="600" max="1200" step="10" value={targetRpm}
              onChange={(e) => setTargetRpm(Number(e.target.value))}
              style={{ width: '100%', marginTop: '0.3rem', cursor: 'pointer', accentColor: 'var(--accent-primary)' }}
            />
          </div>

          {/* Slider 2: Air Jet / Water Pressure */}
          <div className="form-group">
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem', fontWeight: '800' }}>
              <span style={{ color: '#0F172A' }}>2. Nozzle Air Pressure (Bar)</span>
              <span style={{ color: 'var(--status-running)' }}>{jetPressure} Bar</span>
            </div>
            <input
              type="range" min="2.5" max="6.5" step="0.1" value={jetPressure}
              onChange={(e) => setJetPressure(Number(e.target.value))}
              style={{ width: '100%', marginTop: '0.3rem', cursor: 'pointer', accentColor: 'var(--status-running)' }}
            />
          </div>

          {/* Slider 3: Ambient Temperature */}
          <div className="form-group">
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem', fontWeight: '800' }}>
              <span style={{ color: '#0F172A' }}>3. Ambient Factory Temp (°C)</span>
              <span style={{ color: 'var(--status-maintenance)' }}>{ambientTemp}°C</span>
            </div>
            <input
              type="range" min="20" max="48" step="1" value={ambientTemp}
              onChange={(e) => setAmbientTemp(Number(e.target.value))}
              style={{ width: '100%', marginTop: '0.3rem', cursor: 'pointer', accentColor: 'var(--status-maintenance)' }}
            />
          </div>

          {/* Slider 4: Humidity % */}
          <div className="form-group">
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem', fontWeight: '800' }}>
              <span style={{ color: '#0F172A' }}>4. Shed Relative Humidity (%)</span>
              <span style={{ color: 'var(--accent-cyan)' }}>{humidityPct}%</span>
            </div>
            <input
              type="range" min="40" max="90" step="1" value={humidityPct}
              onChange={(e) => setHumidityPct(Number(e.target.value))}
              style={{ width: '100%', marginTop: '0.3rem', cursor: 'pointer', accentColor: 'var(--accent-cyan)' }}
            />
          </div>

          {/* Slider 5: Yarn Tension N */}
          <div className="form-group">
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem', fontWeight: '800' }}>
              <span style={{ color: '#0F172A' }}>5. Warp Yarn Tension (N)</span>
              <span style={{ color: 'var(--status-idle)' }}>{yarnTensionN} N</span>
            </div>
            <input
              type="range" min="10" max="35" step="1" value={yarnTensionN}
              onChange={(e) => setYarnTensionN(Number(e.target.value))}
              style={{ width: '100%', marginTop: '0.3rem', cursor: 'pointer', accentColor: 'var(--status-idle)' }}
            />
          </div>

          {/* Slider 6: Shift Duration Hours */}
          <div className="form-group">
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem', fontWeight: '800' }}>
              <span style={{ color: '#0F172A' }}>6. Operating Shift Duration</span>
              <span style={{ color: 'var(--accent-primary)' }}>{shiftHours} Hours</span>
            </div>
            <input
              type="range" min="8" max="24" step="4" value={shiftHours}
              onChange={(e) => setShiftHours(Number(e.target.value))}
              style={{ width: '100%', marginTop: '0.3rem', cursor: 'pointer', accentColor: 'var(--accent-primary)' }}
            />
          </div>

          {/* Slider 7: Cooling Fan Speed % */}
          <div className="form-group">
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem', fontWeight: '800' }}>
              <span style={{ color: '#0F172A' }}>7. Motor Cooling Fan Speed</span>
              <span style={{ color: 'var(--status-running)' }}>{coolingFanPct}%</span>
            </div>
            <input
              type="range" min="50" max="100" step="5" value={coolingFanPct}
              onChange={(e) => setCoolingFanPct(Number(e.target.value))}
              style={{ width: '100%', marginTop: '0.3rem', cursor: 'pointer', accentColor: 'var(--status-running)' }}
            />
          </div>

          {/* Slider 8: Deferred Service Offset */}
          <div className="form-group">
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem', fontWeight: '800' }}>
              <span style={{ color: '#0F172A' }}>8. Deferred Service Offset</span>
              <span style={{ color: 'var(--status-maintenance)' }}>+{deferredMaintDays} Days</span>
            </div>
            <input
              type="range" min="0" max="30" step="1" value={deferredMaintDays}
              onChange={(e) => setDeferredMaintDays(Number(e.target.value))}
              style={{ width: '100%', marginTop: '0.3rem', cursor: 'pointer', accentColor: 'var(--status-maintenance)' }}
            />
          </div>
        </div>
      </div>

      {/* 13-METRIC SIMULATION OUTCOME BREAKDOWN MATRIX TABLE */}
      <div className="glass-card" style={{ padding: '1.75rem', marginBottom: '1.75rem' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
          <div>
            <h3 style={{ fontSize: '1.1rem', fontWeight: '800', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <Layers size={20} style={{ color: 'var(--accent-primary)' }} /> 13-Metric Simulation Outcome Matrix
            </h3>
            <span style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', fontWeight: '700' }}>
              Real-Time Comparison of Baseline vs Simulated What-If Values Across All 13 Parameters
            </span>
          </div>
        </div>

        <div className="table-responsive">
          <table className="custom-table">
            <thead>
              <tr>
                <th>Operational Metric</th>
                <th>Baseline Value</th>
                <th>Simulated What-If Value</th>
                <th>Delta / Variance</th>
                <th>AI Impact Assessment</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td style={{ fontWeight: '800' }}>1. Motor Temperature (°C)</td>
                <td>{tel.temperature}°C</td>
                <td style={{ fontWeight: '800', color: simTemp > 65 ? 'var(--status-maintenance)' : '#0F172A' }}>{simTemp}°C</td>
                <td style={{ fontWeight: '800', color: simTemp > tel.temperature ? 'var(--status-maintenance)' : 'var(--status-running)' }}>
                  {(simTemp - tel.temperature).toFixed(1)}°C
                </td>
                <td>{simTemp > 65 ? '⚠️ Thermal Stress High' : '✅ Within Thermal Limits'}</td>
              </tr>
              <tr>
                <td style={{ fontWeight: '800' }}>2. Vibration Level (mm/s)</td>
                <td>{tel.vibration} mm/s</td>
                <td style={{ fontWeight: '800', color: simVibration > 2.5 ? 'var(--status-maintenance)' : '#0F172A' }}>{simVibration} mm/s</td>
                <td style={{ fontWeight: '800' }}>{(simVibration - tel.vibration).toFixed(2)} mm/s</td>
                <td>{simVibration > 2.5 ? '⚠️ Bearing Vibration Spike' : '✅ ISO 10816 Compliant'}</td>
              </tr>
              <tr>
                <td style={{ fontWeight: '800' }}>3. Weaving Speed (RPM)</td>
                <td>{tel.rpm} RPM</td>
                <td style={{ fontWeight: '800', color: 'var(--accent-primary)' }}>{targetRpm} RPM</td>
                <td style={{ fontWeight: '800' }}>{targetRpm - tel.rpm} RPM</td>
                <td>{targetRpm > 1050 ? '🚀 High Speed Execution' : '✅ Standard Pick Speed'}</td>
              </tr>
              <tr>
                <td style={{ fontWeight: '800' }}>4. Power Consumption (kW)</td>
                <td>{tel.powerKw} kW</td>
                <td style={{ fontWeight: '800' }}>{simPowerKw} kW</td>
                <td style={{ fontWeight: '800' }}>{(simPowerKw - tel.powerKw).toFixed(1)} kW</td>
                <td>Total Daily: {dailyPowerKwh} kWh</td>
              </tr>
              <tr>
                <td style={{ fontWeight: '800' }}>5. Motor Current Draw (A)</td>
                <td>{tel.motorCurrentA} A</td>
                <td style={{ fontWeight: '800' }}>{simMotorCurrentA} A</td>
                <td style={{ fontWeight: '800' }}>{(simMotorCurrentA - tel.motorCurrentA).toFixed(1)} A</td>
                <td>Electrical Load Rating: Safe</td>
              </tr>
              <tr>
                <td style={{ fontWeight: '800' }}>6. Ambient Humidity (%)</td>
                <td>{tel.humidity}%</td>
                <td style={{ fontWeight: '800' }}>{humidityPct}%</td>
                <td style={{ fontWeight: '800' }}>{(humidityPct - tel.humidity).toFixed(1)}%</td>
                <td>{humidityPct < 50 ? '⚠️ Low Humidity static risk' : '✅ Optimal Shed Moisture'}</td>
              </tr>
              <tr>
                <td style={{ fontWeight: '800' }}>7. Air / Water Pressure (Bar)</td>
                <td>{tel.airPressureBar} bar</td>
                <td style={{ fontWeight: '800' }}>{jetPressure} bar</td>
                <td style={{ fontWeight: '800' }}>{(jetPressure - tel.airPressureBar).toFixed(1)} bar</td>
                <td>Nozzle Pick Insertion Force</td>
              </tr>
              <tr>
                <td style={{ fontWeight: '800' }}>8. Warp Yarn Tension (N)</td>
                <td>{tel.yarnTensionN} N</td>
                <td style={{ fontWeight: '800' }}>{yarnTensionN} N</td>
                <td style={{ fontWeight: '800' }}>{(yarnTensionN - tel.yarnTensionN).toFixed(1)} N</td>
                <td>{yarnTensionN > 22 ? '⚠️ High Warp Break Risk' : '✅ Controlled Shed Clearance'}</td>
              </tr>
              <tr>
                <td style={{ fontWeight: '800' }}>9. Fabric Yield Rate (m/hr)</td>
                <td>{tel.fabricOutputMhr} m/hr</td>
                <td style={{ fontWeight: '800', color: 'var(--status-running)' }}>{simFabricOutputMhr} m/hr</td>
                <td style={{ fontWeight: '800', color: 'var(--status-running)' }}>+{(simFabricOutputMhr - tel.fabricOutputMhr).toFixed(1)} m/hr</td>
                <td style={{ fontWeight: '800', color: 'var(--status-running)' }}>Daily Total: {totalSimOutputMeters.toLocaleString()} Meters</td>
              </tr>
              <tr>
                <td style={{ fontWeight: '800' }}>10. Shift Defect Count</td>
                <td>{tel.defectCount}</td>
                <td style={{ fontWeight: '800', color: simDefectCount > 5 ? 'var(--status-maintenance)' : '#0F172A' }}>{simDefectCount}</td>
                <td style={{ fontWeight: '800' }}>+{simDefectCount - tel.defectCount}</td>
                <td>Scrap Loss: ${totalDefectCost}</td>
              </tr>
              <tr>
                <td style={{ fontWeight: '800' }}>11. Shift Hours Worked</td>
                <td>24 hrs</td>
                <td style={{ fontWeight: '800' }}>{shiftHours} hrs</td>
                <td style={{ fontWeight: '800' }}>{shiftHours - 24} hrs</td>
                <td>Simulated Production Window</td>
              </tr>
              <tr>
                <td style={{ fontWeight: '800' }}>12. Failure Risk (%)</td>
                <td>{tel.failureRiskPct}%</td>
                <td style={{ fontWeight: '800', color: simFailureRiskPct > 15 ? 'var(--status-maintenance)' : 'var(--status-running)' }}>{simFailureRiskPct}%</td>
                <td style={{ fontWeight: '800', color: simFailureRiskPct > tel.failureRiskPct ? 'var(--status-maintenance)' : 'var(--status-running)' }}>+{(simFailureRiskPct - tel.failureRiskPct).toFixed(1)}%</td>
                <td>{simFailureRiskPct > 15 ? '⚠️ High Failure Anomaly Alert' : '✅ Low Risk Profile'}</td>
              </tr>
              <tr>
                <td style={{ fontWeight: '800' }}>13. Remaining Useful Life (RUL)</td>
                <td>{baseRul} Days</td>
                <td style={{ fontWeight: '800', color: 'var(--accent-primary)' }}>{simRulDays} Days</td>
                <td style={{ fontWeight: '800' }}>{simRulDays - baseRul} Days</td>
                <td>Asset Degradation Index</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>

      {/* FINANCIAL IMPACT & PROFIT CALCULATOR */}
      <div className="glass-card" style={{ padding: '1.75rem', marginBottom: '1.75rem', background: 'var(--bg-card)' }}>
        <div style={{ borderBottom: '1px solid var(--border-subtle)', paddingBottom: '0.85rem', marginBottom: '1.25rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h3 style={{ fontSize: '1.1rem', fontWeight: '800', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <DollarSign size={20} style={{ color: 'var(--status-running)' }} /> Financial Profit & Cost Impact Calculator
          </h3>
          <span style={{ fontSize: '0.78rem', color: 'var(--status-running)', fontWeight: '800' }}>Estimated Economics</span>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '1.25rem' }}>
          <div style={{ padding: '1.25rem', background: 'var(--bg-primary)', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border-subtle)' }}>
            <div style={{ fontSize: '0.8rem', color: '#334155', fontWeight: '800' }}>GROSS FABRIC REVENUE</div>
            <div style={{ fontSize: '1.8rem', fontWeight: '900', color: '#0F172A', margin: '4px 0' }}>${grossRevenue.toLocaleString()}</div>
            <div style={{ fontSize: '0.78rem', color: '#334155', fontWeight: '700' }}>@ $4.50 / Meter Fabric</div>
          </div>

          <div style={{ padding: '1.25rem', background: 'var(--bg-primary)', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border-subtle)' }}>
            <div style={{ fontSize: '0.8rem', color: '#334155', fontWeight: '800' }}>POWER & UTILITY COST</div>
            <div style={{ fontSize: '1.8rem', fontWeight: '900', color: 'var(--status-idle)', margin: '4px 0' }}>${totalPowerCost}</div>
            <div style={{ fontSize: '0.78rem', color: '#334155', fontWeight: '700' }}>{dailyPowerKwh} kWh @ $0.15/kWh</div>
          </div>

          <div style={{ padding: '1.25rem', background: 'var(--bg-primary)', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border-subtle)' }}>
            <div style={{ fontSize: '0.8rem', color: '#334155', fontWeight: '800' }}>DEFECT SCRAP LOSS</div>
            <div style={{ fontSize: '1.8rem', fontWeight: '900', color: 'var(--status-maintenance)', margin: '4px 0' }}>${totalDefectCost}</div>
            <div style={{ fontSize: '0.78rem', color: '#334155', fontWeight: '700' }}>{simDefectCount} Defects @ $25/unit</div>
          </div>

          <div style={{ padding: '1.25rem', background: 'var(--status-running-bg)', borderRadius: 'var(--radius-sm)', border: '1px solid rgba(5, 150, 105, 0.4)' }}>
            <div style={{ fontSize: '0.8rem', color: 'var(--status-running)', fontWeight: '800' }}>NET SIMULATED PROFIT</div>
            <div style={{ fontSize: '2rem', fontWeight: '900', color: 'var(--status-running)', margin: '4px 0' }}>${netProfit.toLocaleString()}</div>
            <div style={{ fontSize: '0.78rem', color: 'var(--status-running)', fontWeight: '800' }}>Estimated Margin per Shift</div>
          </div>
        </div>
      </div>

      {/* Comparison Chart Section */}
      <div className="glass-card" style={{ padding: '1.75rem' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
          <div>
            <h3 style={{ fontSize: '1.1rem', fontWeight: '800', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <TrendingUp size={20} style={{ color: 'var(--accent-primary)' }} /> Baseline vs Simulated What-If Comparison
            </h3>
            <span style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', fontWeight: '700' }}>
              Comparative Analysis Across Yield, Risk %, Power (kW), Temp (°C), & Remaining Life
            </span>
          </div>
        </div>
        <div style={{ height: '260px', width: '100%' }}>
          <Bar data={chartData} options={chartOptions} />
        </div>
      </div>
    </div>
  );
};

export default WhatIfSimulationPage;
